const p = $input.item.json;

const miastoZ = p.miasto_z || '';
const miastoDo = p.miasto_do || '';
const pokoje = Number(p.liczba_pokoi) || 1;
const pietroZ = Number(p.pietro_z) || 0;
const windaZ = !!p.winda_z;
const pietroDo = Number(p.pietro_do) || 0;
const windaDo = !!p.winda_do;
const pakowanie = !!p.pakowanie;
const demontaz = !!p.demontaz_mebli;
const pianinoSejf = !!p.pianino_lub_sejf;

const BASE_PER_POKOJ = 350;
const cenaBazowa = pokoje * BASE_PER_POKOJ;

function doplataZaSchody(pietro, winda) {
  if (winda || pietro <= 0) return 0;
  return pietro * 60;
}

let doplaty = 0;
doplaty += doplataZaSchody(pietroZ, windaZ);
doplaty += doplataZaSchody(pietroDo, windaDo);
if (pakowanie) doplaty += pokoje * 80;
if (demontaz) doplaty += 150;
if (pianinoSejf) doplaty += 300;

const min = Math.round((cenaBazowa + doplaty) * 0.9);
const max = Math.round((cenaBazowa + doplaty) * 1.15);

const skladniki = [];
skladniki.push('baza: ' + pokoje + ' pok. x ' + BASE_PER_POKOJ + ' zl = ' + cenaBazowa + ' zl');
if (doplataZaSchody(pietroZ, windaZ) > 0) skladniki.push('brak windy przy wyjsciu (pietro ' + pietroZ + '): +' + doplataZaSchody(pietroZ, windaZ) + ' zl');
if (doplataZaSchody(pietroDo, windaDo) > 0) skladniki.push('brak windy przy dojsciu (pietro ' + pietroDo + '): +' + doplataZaSchody(pietroDo, windaDo) + ' zl');
if (pakowanie) skladniki.push('pakowanie: +' + (pokoje * 80) + ' zl');
if (demontaz) skladniki.push('demontaz/montaz mebli: +150 zl');
if (pianinoSejf) skladniki.push('transport pianina/sejfu: +300 zl');

return 'WIDELKI CENOWE: ' + min + '-' + max + ' zl. Trasa: ' + miastoZ + ' -> ' + miastoDo + '. Skladniki wyceny: ' + skladniki.join('; ') + '.';
